<?php declare(strict_types=1); $e=static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, "UTF-8"); ?><style>.cr-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cr-stat{padding:22px;border-radius:14px}.cr-stat .n{font-size:30px;font-weight:700}.cr-muted{color:#667085}.cr-actions{display:flex;gap:8px;flex-wrap:wrap}.cr-badge{display:inline-block;padding:5px 9px;border-radius:999px;font-size:12px;background:#eef2f6}@media(max-width:900px){.cr-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr!important}}</style><div class="page-header"><div><h1>Vehicles & Equipment</h1><p>Manage individual commercial rental assets.</p></div><div class="page-actions"><a class="btn btn-primary" href="<?= config('app.base_path') ?>/commercial-rentals/vehicles/create">Add Vehicle / Equipment</a></div></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Asset</th><th>Provider</th><th>Category</th><th>Rate</th><th>Availability</th><th>Actions</th></tr></thead><tbody><?php if(empty($vehicles)): ?><tr><td colspan="6"><div class="empty-state">No vehicles or equipment found.</div></td></tr><?php else: foreach($vehicles as $row): ?><tr><td><strong><?= $e($row['name']) ?></strong><br><span class="cr-muted"><?= $e($row['registration_no'] ?? '') ?></span></td><td><?= $e($row['provider_name']) ?></td><td><?= $e($row['category_name'] ?? '—') ?></td><td><?= $e($row['rate_type']) ?><?php if((float)$row['rate']>0): ?> · ₹<?= number_format((float)$row['rate'],2) ?><?php endif; ?></td><td><?= $e($row['availability']) ?></td><td><a class="link-button" href="<?= config('app.base_path') ?>/commercial-rentals/vehicles/<?= (int)$row['id'] ?>">View</a> <a class="link-button" href="<?= config('app.base_path') ?>/commercial-rentals/vehicles/<?= (int)$row['id'] ?>/edit">Edit</a></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
